package com.bautruc.ecommerce.payment.domain;import static org.assertj.core.api.Assertions.assertThat;import java.time.Instant;import org.junit.jupiter.api.Test;class PaymentTest{@Test void createsPendingForExactlyFifteenMinutes(){Instant now=Instant.parse("2026-08-13T00:00:00Z");Payment p=new Payment(1L,1000,now);assertThat(p.getStatus()).isEqualTo(PaymentStatus.PENDING);assertThat(p.getProvider()).isEqualTo(PaymentProvider.PAYOS);assertThat(p.getExpiresAt()).isEqualTo(now.plusSeconds(900));}}
